import{H as e,V as t,et as n,j as r}from"./chunks/framework.c0x6U8zS.js";var i=JSON.parse(`{"title":"AHE04 STM32 ↔ ESP32 串口协议","description":"","frontmatter":{},"headers":[],"relativePath":"products/ahe04/spf-protocol.md","filePath":"products/ahe04/spf-protocol.md","lastUpdated":1787659512000}`),a={name:`products/ahe04/spf-protocol.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="ahe04-stm32-↔-esp32-串口协议" tabindex="-1">AHE04 STM32 ↔ ESP32 串口协议 <a class="header-anchor" href="#ahe04-stm32-↔-esp32-串口协议" aria-label="Permalink to “AHE04 STM32 ↔ ESP32 串口协议”">​</a></h1><p>AHE04 主板 <strong>STM32</strong> 与网关 <strong>ESP32</strong> 之间的 UART 命令字典（SPF 的 CMD / OP / ORIGIN / VALUE）。组帧、校验、粘包见 <a href="/ahs-docs-page/common/spf-packet-v2.html">SPF 数据包格式 V2（含 ORIGIN）</a>，本文不再重复帧结构。</p><p>面向 <strong>嵌入式工程师</strong>（主板与网关对照）。APP 工程师看 <a href="./ble-protocol.html">BLE 协议</a>，不要直接发 SPF。</p><div class="vp-table-wrap"><table tabindex="0"><thead><tr><th>你要找什么</th><th>看哪一节</th></tr></thead><tbody><tr><td>谁先发、UART、OP、写应答</td><td><a href="#_1-接入约定">§1 接入约定</a></td></tr><tr><td>CMD、方向、VALUE</td><td><a href="#_2-命令总表">§2 命令总表</a></td></tr><tr><td>标定 / 睡眠报告 / 关机 / 音乐通道</td><td><a href="#_3-交互时序">§3 交互时序</a></td></tr><tr><td>对照 hex</td><td><a href="#_4-抓包举例">§4 抓包举例</a></td></tr><tr><td>SPF CMD 与 BLE cmd 对照</td><td><a href="#_5-与-ble-对照">§5 与 BLE 对照</a></td></tr><tr><td>头文件里有、当前未处理的码</td><td><a href="#_6-保留命令">§6 保留命令</a></td></tr></tbody></table></div><ul><li><strong>适用</strong>：AHE04 主板固件（<code>spf_cmd.h</code> / <code>esp32_spf.c</code>）</li><li><strong>封装</strong>：<a href="/ahs-docs-page/common/spf-packet-v2.html">SPF 数据包格式 V2（含 ORIGIN）</a></li><li><strong>空中命令</strong>：<a href="./ble-protocol.html">BLE 协议</a></li></ul><hr><h2 id="_1-接入约定" tabindex="-1">1. 接入约定 <a class="header-anchor" href="#_1-接入约定" aria-label="Permalink to “1. 接入约定”">​</a></h2><h3 id="_1-1-链路" tabindex="-1">1.1 链路 <a class="header-anchor" href="#_1-1-链路" aria-label="Permalink to “1.1 链路”">​</a></h3><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>APP  ←—— BLE ——→  ESP32 网关  ←—— USART1 / 115200 8N1（SPF）——→  STM32 主板</span></span></code></pre></div><div class="vp-table-wrap"><table tabindex="0"><thead><tr><th>角色</th><th>做什么</th></tr></thead><tbody><tr><td>ESP32</td><td>对 APP 走 BLE；把控制类读写转成 SPF 发给主板；把主板应答 / 通知转回 BLE</td></tr><tr><td>STM32</td><td>气囊、加热、负离子、BCG、本地音乐等业务；收 ESP32 的读写；主动 NOTIFY 实时数据与睡眠报告</td></tr></tbody></table></div><p>物理层与帧格式见 <a href="/ahs-docs-page/common/spf-packet-v2.html">SPF 数据包格式 V2</a>。主板解析半帧超时 <strong>5 秒</strong>。</p><p>ESP32 把 APP 经 BLE 下发的读写转成 SPF 时填入 <strong>ORIGIN = <code>0x01</code></strong>；STM32 写应答 / 读应答须<strong>原样回写</strong>同一 ORIGIN。ORIGIN 含义见 <a href="/ahs-docs-page/common/spf-packet-v2.html#_2-origin-发起者">spf-packet-v2 §2</a>。</p><p>多数控制命令路径：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>APP 写 BLE → ESP32 组 SPF 写给 STM32 → STM32 处理并回写应答 → ESP32 从 BLE 应答 APP</span></span></code></pre></div><h3 id="_1-2-op-与写应答" tabindex="-1">1.2 OP 与写应答 <a class="header-anchor" href="#_1-2-op-与写应答" aria-label="Permalink to “1.2 OP 与写应答”">​</a></h3><div class="vp-table-wrap"><table tabindex="0"><thead><tr><th>OP</th><th>名称</th><th>本链路典型方向</th></tr></thead><tbody><tr><td><code>0x00</code></td><td>写</td><td>ESP32 → STM32（控制）；个别由 STM32 → ESP32（见 §2）</td></tr><tr><td><code>0x01</code></td><td>写应答</td><td>STM32 → ESP32</td></tr><tr><td><code>0x02</code></td><td>读</td><td>ESP32 → STM32</td></tr><tr><td><code>0x03</code></td><td>读应答</td><td>STM32 → ESP32</td></tr><tr><td><code>0xFF</code></td><td>通知</td><td>STM32 → ESP32（实时数据、睡眠报告）</td></tr></tbody></table></div><p>写应答 VALUE 默认 <strong>1 字节：<code>0x01</code> 成功，<code>0x00</code> 失败</strong>。例外在命令表里写明（枕高极限 <code>0x02</code>、标定完成 3 字节、关机就绪 <code>0x00</code>）。</p><p>多字节一律 <strong>大端</strong>。</p><h3 id="_1-3-谁主动发" tabindex="-1">1.3 谁主动发 <a class="header-anchor" href="#_1-3-谁主动发" aria-label="Permalink to “1.3 谁主动发”">​</a></h3><div class="vp-table-wrap"><table tabindex="0"><thead><tr><th>类型</th><th>发起方</th><th>例子</th></tr></thead><tbody><tr><td>配置读写</td><td>ESP32（来自 APP）</td><td>加热、负离子、闹钟、参数寄存器</td></tr><tr><td>网关状态</td><td>ESP32</td><td>蓝牙连接状态、电源键、关机请求、产品型号</td></tr><tr><td>周期 / 事件上报</td><td>STM32</td><td>实时数据 1 秒一次；睡眠报告 NOTIFY；报告结束状态</td></tr><tr><td>硬件通道</td><td>STM32 也可写</td><td>音乐通道 / PA，让网关切功放</td></tr></tbody></table></div><hr><h2 id="_2-命令总表" tabindex="-1">2. 命令总表 <a class="header-anchor" href="#_2-命令总表" aria-label="Permalink to “2. 命令总表”">​</a></h2><p>按 <strong>CMD 从小到大</strong>。方向以「谁发出写/读/通知」为准。写应答若无另写，均为 1 字节 <code>0x01</code> / <code>0x00</code>。</p><div class="vp-table-wrap"><table tabindex="0"><thead><tr><th>cmd</th><th>名称</th><th>OP</th><th>VALUE</th></tr></thead><tbody><tr><td><code>0x20</code></td><td>系统指示灯</td><td>写 <code>0x00→0x01</code> 读 <code>0x02→0x03</code></td><td>对应 BLE <code>0x07</code>，ESP32 <strong>透传</strong> STM32，ORIGIN=<code>0x01</code><br>写：1 字节<br><code>0</code> 关<br><code>1</code>–<code>200</code> 开 n 秒<br><code>255</code> 常亮<br><code>201</code>–<code>254</code> 非法，写应答 <code>0x00</code><br>读：无 value<br>读应答：回上次写入的那 1 字节</td></tr><tr><td><code>0x21</code></td><td>智能睡眠模式</td><td>写 <code>0x00→0x01</code> 读 <code>0x02→0x03</code></td><td>对应 BLE <code>0x0A</code>，ESP32 <strong>透传</strong> STM32，ORIGIN=<code>0x01</code><br>写：1 字节<br><code>0</code> 关<br><code>1</code> 开<br>读：无 value<br>读应答：1 字节，同写</td></tr><tr><td><code>0x22</code></td><td>PA 增益设置</td><td>写 <code>0x00→0x01</code> 读 <code>0x02→0x03</code></td><td>对应 BLE <code>0x0B</code>，ESP32 <strong>透传</strong> STM32，ORIGIN=<code>0x01</code><br>写：2 字节<br><code>[0]</code> 通道 <code>0</code> 喇叭 / <code>1</code> 振子<br><code>[1]</code> 增益挡位 <strong>0–7</strong>（共 8 挡）<br>非法通道或增益 &gt;7：写应答 <code>0x00</code><br>读：1 字节 <code>[0]</code> 指定通道<br>读应答：2 字节，布局同写</td></tr><tr><td><code>0x40</code></td><td>音乐通道选择</td><td>写 <code>0x00→0x01</code> 读 <code>0x02→0x03</code></td><td>ESP32→STM32：<br><code>0x00</code> 蓝牙音响<br><code>0x01</code> 本地离线<br><code>0x02</code> 临时关 PA（不改已存模式）<br>非法值写应答 <code>0x00</code><br>STM32 也可主动写给 ESP32：<br><code>0x00</code> 杰里蓝牙且 PA 开<br><code>0x01</code> 本地音乐且 PA 开<br><code>0x02</code> PA 关（仅本地模式允许）<br>读应答 1 字节：当前已存模式 <code>0/1</code></td></tr><tr><td><code>0x70</code></td><td>本地音乐配置</td><td>写 <code>0x00→0x01</code> 读 <code>0x02→0x03</code></td><td>至少 9 字节<br><code>[0]</code> 开关 0 关 / 1 开<br><code>[1]</code> 模式 0 单次 / 1 循环<br><code>[2-5]</code> 播放列表 4 字节位图，大端，bit31–0 对应 ID32–1<br><code>[6-7]</code> 工作时长（分钟）<br><code>[8]</code> 音量 0–100<br>写时 <code>en=1</code> 且列表非空则启动播放，否则停止</td></tr><tr><td><code>0x80</code></td><td>本地音乐音量</td><td>写 <code>0x00→0x01</code> 读 <code>0x02→0x03</code></td><td>1 字节 0–100</td></tr><tr><td><code>0x81</code></td><td>本地音乐控制</td><td>写 <code>0x00→0x01</code></td><td><code>0x01</code> 按当前列表播放<br>其它值停止</td></tr><tr><td><code>0x90</code></td><td>枕头基础高度</td><td>写 <code>0x00→0x01</code> 读 <code>0x02→0x03</code></td><td>写：6 字节 <code>air1…air6</code> 各 1 字节挡位（当前主板只应答、未写入存储）<br>读应答：当前 <strong>1 字节</strong> 基础高度方向（与 BLE 六路读应答不同，以本帧为准）</td></tr><tr><td><code>0xA1</code></td><td>加热</td><td>写 <code>0x00→0x01</code> 读 <code>0x02→0x03</code></td><td><code>[0]</code> 开关 0 关 / 1 开<br><code>[1-2]</code> 时长（分钟）<br><code>[3]</code> 挡位 1 低 / 2 中 / 3 高</td></tr><tr><td><code>0xA2</code></td><td>临时控制外设</td><td>写 <code>0x00→0x01</code></td><td><code>0x01</code>：当前外设在跑则全停，否则按已存配置一键启动（负离子 / 加热 / 本地音乐）<br>不写存储</td></tr><tr><td><code>0xA3</code></td><td>系统提示音音量</td><td>写 <code>0x00→0x01</code> 读 <code>0x02→0x03</code></td><td>1 字节：<code>0</code> 关，<code>1</code>–<code>100</code> 音量</td></tr><tr><td><code>0xA7</code></td><td>负离子</td><td>写 <code>0x00→0x01</code> 读 <code>0x02→0x03</code></td><td><code>[0]</code> 开关 0 关 / 1 开<br><code>[1-2]</code> 工作时长（分钟）<br><code>[3]</code> 浓度 0–100</td></tr><tr><td><code>0xC0</code></td><td>实时数据</td><td>通知 <code>0xFF</code></td><td>STM32 → ESP32，约 <strong>1 秒</strong> 一帧，14 字节，见 <a href="#_2-1-实时数据-0xc0">§2.1</a></td></tr><tr><td><code>0xC2</code></td><td>日期和时间</td><td>写 <code>0x00→0x01</code> 读 <code>0x02→0x03</code></td><td>写 7 字节：<code>[0-1]</code> 年、<code>[2]</code> 月、<code>[3]</code> 日、<code>[4]</code> 时、<code>[5]</code> 分、<code>[6]</code> 秒（24 小时，北京时间）<br>写成功后主板同步能斯达模组时钟<br>读应答见 <a href="#_2-2-rtc-读应答">§2.2</a></td></tr><tr><td><code>0xC3</code></td><td>模拟止鼾开关</td><td>写 <code>0x00→0x01</code></td><td>当前主板仅回写应答，无业务</td></tr><tr><td><code>0xC4</code></td><td>蓝牙连接状态</td><td>写 <code>0x00</code>（无应答）</td><td>ESP32 → STM32，<code>[0]</code> 是否已连接。主板只记录，不回写应答</td></tr><tr><td><code>0xC5</code></td><td>舒曼波控制</td><td>写 <code>0x00→0x01</code></td><td>当前主板仅回写应答，无业务</td></tr><tr><td><code>0xC6</code></td><td>智能枕高匹配</td><td>写 <code>0x00→0x01</code> 读 <code>0x02→0x03</code></td><td>1 字节：<code>0</code> 关 / <code>1</code> 智能+体动 / <code>2</code> 仅智能 / <code>3</code> 仅体动</td></tr><tr><td><code>0xC7</code></td><td>关机</td><td>写 <code>0x00</code>；就绪后 STM32 主动写应答</td><td>ESP32 写 <code>[0]=0</code>：主板走电源键长按关机流程，<strong>当时不回写应答</strong><br>准备好掉电后再发写应答 1 字节 <code>0x00</code>（此处 <code>0x00</code> 表示「可以断电」，不是失败）</td></tr><tr><td><code>0xC8</code></td><td>主板固件版本</td><td>读 <code>0x02→0x03</code></td><td>读应答 3 字节：<code>[0-1]</code> 版本号大端、<code>[2]</code> PLID（AHE04 当前固定 <code>0x01</code>）</td></tr><tr><td><code>0xC9</code></td><td>故障代码</td><td>读 <code>0x02→0x03</code></td><td>读应答 4 字节大端位图，见 <a href="#_2-3-故障代码">§2.3</a></td></tr><tr><td><code>0xCA</code></td><td>产品型号</td><td>写 <code>0x00→0x01</code></td><td><code>[0]</code> 型号 0=AHE01 / 1=AHE02 / 2=AHE03 / 3=AHE04<br>当前主板仅日志 + 应答，不改本地型号</td></tr><tr><td><code>0xCB</code></td><td>进入标定模式</td><td>写 <code>0x00→0x01</code></td><td><code>0x01</code> 进入 / <code>0x00</code> 退出。进入后标定步骤复位</td></tr><tr><td><code>0xCC</code></td><td>调节枕高</td><td>写 <code>0x00→0x01</code> 读 <code>0x02→0x03</code></td><td>写 1 字节动作码，见 <a href="#_2-4-枕高动作码">§2.4</a><br>写应答 <code>0x01</code> 已执行 / <code>0x02</code> 已到气压极限（仍会按动作执行）<br>模式与动作码不匹配则不应答</td></tr><tr><td><code>0xCD</code></td><td>开始标定 1（仰卧）</td><td>写 <code>0x00→0x01</code></td><td>写后立即 1 字节 <code>0x01</code>（已收到）<br>标定完成后 <strong>再发一次</strong> 写应答 3 字节：<code>[0]</code> <code>0x01</code> 成功、<code>[1-2]</code> 当前气压。对接以 3 字节这次为准</td></tr><tr><td><code>0xCE</code></td><td>开始标定 2（侧卧）</td><td>写 <code>0x00→0x01</code></td><td>同上：先 1 字节收到，再 3 字节结果<br><code>[0]</code> <code>0x01</code> 成功 / <code>0x00</code> 失败（压差条件不满足等）、<code>[1-2]</code> 气压</td></tr><tr><td><code>0xD0</code></td><td>请求 BCG 睡眠报告</td><td>写 <code>0x00→0x01</code></td><td>至少 6 字节<br><code>[0-3]</code> 时间戳（目前未用）<br><code>[4]</code> 请求类型 <code>0x00</code> 开始 / <code>0x01</code> 下一条 / <code>0x02</code> 上一条 / <code>0x03</code> 停止<br><code>[5]</code> 生成模式，仅类型 <code>0x00</code> 时有效：<code>0x00</code> 普通 / <code>0x01</code> 立即生成</td></tr><tr><td><code>0xD1</code></td><td>睡眠报告传输状态</td><td>STM32 主动写 <code>0x00</code></td><td>9 字节：<code>[0]</code> 状态 <code>0x01</code> 正常结束 / <code>0x02</code> 中断<br><code>[1-4]</code> 报告总字节数<br><code>[5-8]</code> 原始数据总字节数<br>对应 BLE <code>0x31</code></td></tr><tr><td><code>0xD2</code></td><td>睡眠报告</td><td>通知 <code>0xFF</code></td><td>STM32 → ESP32，每条报告 payload（转 BLE 前为 30 字节，见 BLE 附录 3）</td></tr><tr><td><code>0xD3</code></td><td>睡眠报告原始数据</td><td>通知 <code>0xFF</code></td><td>STM32 → ESP32，供折线图。结构见 BLE 附录 4</td></tr><tr><td><code>0xD4</code></td><td>报表应答</td><td>写 <code>0x00</code></td><td>ESP32 → STM32，告知已收到报告帧。当前主板收到后不处理</td></tr><tr><td><code>0xD5</code></td><td>制作 BCG 假数据</td><td>写 <code>0x00→0x01</code></td><td>调试用，触发模组生成测试报告</td></tr><tr><td><code>0xD9</code></td><td>闹钟设置</td><td>写 <code>0x00→0x01</code> 读 <code>0x02→0x03</code></td><td>13 字节，见 <a href="#_2-5-闹钟">§2.5</a></td></tr><tr><td><code>0xDA</code></td><td>临时关闹钟</td><td>写 <code>0x00→0x01</code></td><td>停当前已响闹钟并停本地音乐工作流，不影响已存闹钟配置</td></tr><tr><td><code>0xDB</code></td><td>SIM120 蓝牙开关</td><td>写 <code>0x00→0x01</code></td><td><code>[0]</code> <code>0x00</code> 关 / <code>0x01</code> 开，转发给能斯达模组</td></tr><tr><td><code>0xDC</code></td><td>开机按键</td><td>写 <code>0x00→0x01</code></td><td>ESP32 → STM32。<code>[0]</code> <code>0x01</code> 短按 / <code>0x02</code> 长按<br>工厂模式下短按切换测试外设，不走正常电源键逻辑</td></tr><tr><td><code>0xDE</code></td><td>工厂测试模式</td><td>写 <code>0x00→0x01</code> 读 <code>0x02→0x03</code></td><td><code>[0]</code> <code>0x00</code> 关 / <code>0x01</code> 开</td></tr><tr><td><code>0xE0</code></td><td>参数寄存器 1</td><td>写 <code>0x00→0x01</code> 读 <code>0x02→0x03</code></td><td><strong>【预留占位】</strong> 14 字节，布局同 AHE01 BLE <code>0xFA</code>，当前勿当功能用<br>写应答 1 字节成功/失败，不回显 14 字节</td></tr><tr><td><code>0xE1</code></td><td>参数寄存器 2</td><td>读 <code>0x02→0x03</code></td><td>读应答 <strong>7</strong> 字节：<code>[0-1]</code> 实时原始气压、<code>[2-3]</code> 滤波气压、<code>[4-5]</code> 仰卧/侧卧气压变化量、<code>[6]</code> 卧姿 0 未初始化 / 1 仰卧 / 2 侧卧<br>（BLE <code>0xFB</code> 按 14 字节描述，多出的字节由网关补 0）</td></tr><tr><td><code>0xE2</code></td><td>参数寄存器 3</td><td>读 <code>0x02→0x03</code></td><td>智能匹配非 0：7 字节 <code>[0]</code> 开关、仰卧气压 2B、侧卧气压 2B、侧卧采样气压 2B<br>智能匹配为 0：3 字节 <code>[0]=0</code>、手动基础枕高气压 2B</td></tr></tbody></table></div><h3 id="_2-1-实时数据-0xc0" tabindex="-1">2.1 实时数据 <code>0xC0</code> <a class="header-anchor" href="#_2-1-实时数据-0xc0" aria-label="Permalink to “2.1 实时数据 0xC0”">​</a></h3><p>STM32 主动 NOTIFY，14 字节（与 BLE 实时数据 <code>0x01</code> 布局一致）：</p><div class="vp-table-wrap"><table tabindex="0"><thead><tr><th>偏移</th><th>字段</th></tr></thead><tbody><tr><td><code>[0]</code></td><td>bit3–0 型号 0=AHE01 / 1=AHE02 / 2=AHE03 / 3=AHE04</td></tr><tr><td><code>[1]</code></td><td>BCG 心率</td></tr><tr><td><code>[2]</code></td><td>BCG 呼吸率</td></tr><tr><td><code>[3]</code></td><td>BCG 睡眠状态：0 离床 / 1 在床 / 2 在床体动 / 3 呼吸暂停 / 4 体重 / 5 打鼾</td></tr><tr><td><code>[4]</code></td><td>status1：bit0 负离子、bit1 加热、bit2 闹钟响、bit3 音乐播放、bit4 通道 0 蓝牙 / 1 本地</td></tr><tr><td><code>[5]</code></td><td>status2：bit1–0 加热挡位 01 低 / 10 中 / 11 高；bit7–2 当前音乐 ID 1–32</td></tr><tr><td><code>[6-7]</code></td><td>负离子运行时长（分钟）</td></tr><tr><td><code>[8-9]</code></td><td>加热运行时长（分钟）</td></tr><tr><td><code>[10-11]</code></td><td>音乐播放时长（分钟）</td></tr><tr><td><code>[12-13]</code></td><td>气压</td></tr></tbody></table></div><p>同步睡眠报告期间主板暂停发本帧。</p><h3 id="_2-2-rtc-读应答" tabindex="-1">2.2 RTC 读应答 <a class="header-anchor" href="#_2-2-rtc-读应答" aria-label="Permalink to “2.2 RTC 读应答”">​</a></h3><p>读 <code>0xC2</code> 时主板先按本地 RTC 回 <strong>8 字节</strong>：年（2）月日<strong>星期</strong>时分秒。</p><p>能斯达模组对时应答到达后，主板可能再发一帧读应答 <strong>12 字节</strong>（与 BLE <code>0x20</code> 读应答对齐）：年（2）月日时分秒 + 时间戳 4B + 时区 1B（无星期）。网关转 BLE 时用 12 字节这帧。</p><h3 id="_2-3-故障代码" tabindex="-1">2.3 故障代码 <a class="header-anchor" href="#_2-3-故障代码" aria-label="Permalink to “2.3 故障代码”">​</a></h3><p>4 字节大端，位置 1 为故障，解除后清 0。</p><div class="vp-table-wrap"><table tabindex="0"><thead><tr><th>位</th><th>宏</th><th>含义</th></tr></thead><tbody><tr><td>bit5</td><td><code>FAULTCODE_PUMP_RUNTIME</code></td><td>泵连续充/放超时（180 s）</td></tr><tr><td>bit4</td><td><code>FAULTCODE_PUMP</code></td><td>泵故障（电流过高）</td></tr><tr><td>bit3</td><td><code>FAULTCODE_BCG_COMM</code></td><td>BCG 通讯故障</td></tr><tr><td>bit2</td><td><code>FAULTCODE_ESP32_COMM</code></td><td>与 ESP32 通讯故障</td></tr><tr><td>bit1</td><td><code>FAULTCODE_POWEROFF</code></td><td>关机异常</td></tr><tr><td>bit0</td><td><code>FAULTCODE_PRN_BIT</code></td><td>气压传感器故障</td></tr></tbody></table></div><h3 id="_2-4-枕高动作码" tabindex="-1">2.4 枕高动作码 <a class="header-anchor" href="#_2-4-枕高动作码" aria-label="Permalink to “2.4 枕高动作码”">​</a></h3><p>与泵阀方向枚举数值无关，按协议码映射。必须先处于对应模式，否则主板丢弃且不回写应答。</p><div class="vp-table-wrap"><table tabindex="0"><thead><tr><th>VALUE</th><th>前置</th><th>动作</th></tr></thead><tbody><tr><td><code>0x01</code></td><td>已进入标定（<code>0xCB</code> = 1）</td><td>充气</td></tr><tr><td><code>0x02</code></td><td>已进入标定</td><td>放气</td></tr><tr><td><code>0x03</code></td><td>已进入标定</td><td>停止</td></tr><tr><td><code>0x11</code></td><td>非标定（<code>0xCB</code> = 0）</td><td>充气</td></tr><tr><td><code>0x12</code></td><td>非标定</td><td>放气</td></tr><tr><td><code>0x13</code></td><td>非标定</td><td>停止</td></tr></tbody></table></div><p>标定流程里 APP 周期下发充/放（建议 ≥3 秒），停止发 1 次。</p><h3 id="_2-5-闹钟" tabindex="-1">2.5 闹钟 <a class="header-anchor" href="#_2-5-闹钟" aria-label="Permalink to “2.5 闹钟”">​</a></h3><p>13 字节，读写布局相同：</p><div class="vp-table-wrap"><table tabindex="0"><thead><tr><th>偏移</th><th>含义</th></tr></thead><tbody><tr><td><code>[0]</code></td><td>开关 0 关 / 1 开</td></tr><tr><td><code>[1]</code></td><td>时 0–24</td></tr><tr><td><code>[2]</code></td><td>分 0–60</td></tr><tr><td><code>[3]</code></td><td>重复 0 一次 / 1 每天 / 2 自定义</td></tr><tr><td><code>[4]</code></td><td>星期 bit6–0 = 六…日（自定义时有效）</td></tr><tr><td><code>[5]</code></td><td>音乐 ID</td></tr><tr><td><code>[6]</code></td><td>负离子唤醒 0 关 / 1–100 浓度</td></tr><tr><td><code>[7]</code></td><td>加热唤醒 0 关 / 1 低 / 2 中 / 3 高</td></tr><tr><td><code>[8]</code></td><td>香薰唤醒（当前未用）</td></tr><tr><td><code>[9]</code></td><td>LED 唤醒（当前未用）</td></tr><tr><td><code>[10]</code></td><td>响铃模式 0 渐变 / 1 固定</td></tr><tr><td><code>[11]</code></td><td>响铃音量 1–100</td></tr><tr><td><code>[12]</code></td><td>持续 0 一直响 / n 分钟</td></tr></tbody></table></div><hr><h2 id="_3-交互时序" tabindex="-1">3. 交互时序 <a class="header-anchor" href="#_3-交互时序" aria-label="Permalink to “3. 交互时序”">​</a></h2><h3 id="_3-1-标定枕高" tabindex="-1">3.1 标定枕高 <a class="header-anchor" href="#_3-1-标定枕高" aria-label="Permalink to “3.1 标定枕高”">​</a></h3><ol><li>写 <code>0xCB</code> = <code>0x01</code> 进入标定，等写应答。</li><li>周期写 <code>0xCC</code> = <code>0x01</code>/<code>0x02</code> 调高/调低，停止写 <code>0x03</code>。应答 <code>0x02</code> 表示已到极限。</li><li>写 <code>0xCD</code> 开始标定 1，等约 10 秒收 <strong>3 字节</strong>写应答（不要把刚收到的 1 字节「已收到」当成标定完成）。</li><li>再调高度后写 <code>0xCE</code> 开始标定 2，同样等 3 字节结果。失败时主板会关智能匹配。</li><li>写 <code>0xCB</code> = <code>0x00</code> 退出（正常结束时主板也会自行退出标定）。</li></ol><h3 id="_3-2-睡眠报告" tabindex="-1">3.2 睡眠报告 <a class="header-anchor" href="#_3-2-睡眠报告" aria-label="Permalink to “3.2 睡眠报告”">​</a></h3><ol><li>ESP32 写 <code>0xD0</code>：类型 <code>0x00</code> + 生成模式，STM32 回写应答后向 BCG 要报告。</li><li>STM32 用 <code>0xD2</code> / <code>0xD3</code> NOTIFY 上送报告与原始数据。</li><li>需要下一条 / 上一条 / 停止时再写 <code>0xD0</code> 对应类型。</li><li>结束时 STM32 写 <code>0xD1</code>（9 字节状态与长度）。网关转成 BLE <code>0x31</code> 通知。</li></ol><p>同步过程中不发 <code>0xC0</code> 实时数据。</p><h3 id="_3-3-关机" tabindex="-1">3.3 关机 <a class="header-anchor" href="#_3-3-关机" aria-label="Permalink to “3.3 关机”">​</a></h3><ol><li>ESP32 写 <code>0xC7</code>，VALUE <code>0x00</code>。</li><li>STM32 <strong>先不回</strong>写应答，去做关机准备。</li><li>就绪后 STM32 发 <code>0xC7</code> 写应答，VALUE <code>0x00</code>。ESP32 据此硬件掉电。</li></ol><p>不要把这次 <code>0x00</code> 当成失败重试。</p><h3 id="_3-4-音乐通道与-pa" tabindex="-1">3.4 音乐通道与 PA <a class="header-anchor" href="#_3-4-音乐通道与-pa" aria-label="Permalink to “3.4 音乐通道与 PA”">​</a></h3><ul><li>APP/网关切通道：ESP32 写 <code>0x40</code> = <code>0/1/2</code>，STM32 存模式并<strong>再写一帧</strong> <code>0x40</code> 给 ESP32，让网关切功放。</li><li>本地音乐停播需要静音时：STM32 在离线模式下可写 <code>0x40</code> = <code>0x02</code> 关 PA；蓝牙音箱模式禁止关 PA。</li></ul><hr><h2 id="_4-抓包举例" tabindex="-1">4. 抓包举例 <a class="header-anchor" href="#_4-抓包举例" aria-label="Permalink to “4. 抓包举例”">​</a></h2><p>帧头固定 <code>5A A5</code>，LENGTH 大端，含 ORIGIN，最后 1 字节 CHECK。计算见 <a href="/ahs-docs-page/common/spf-packet-v2.html">SPF 数据包格式 V2</a> §3。</p><h3 id="_4-1-写加热-开、30-分钟、中档-origin-ble" tabindex="-1">4.1 写加热（开、30 分钟、中档，ORIGIN=BLE） <a class="header-anchor" href="#_4-1-写加热-开、30-分钟、中档-origin-ble" aria-label="Permalink to “4.1 写加热（开、30 分钟、中档，ORIGIN=BLE）”">​</a></h3><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ESP32：5A A5 00 08 A1 00 01 01 00 1E 02 CHECK</span></span>
<span class="line"><span>              │     │  │  │  └─ VALUE：en=1, 时长=0x001E, 挡位=2</span></span>
<span class="line"><span>              │     │  │  └─ ORIGIN=0x01</span></span>
<span class="line"><span>              │     │  └─ OP 写</span></span>
<span class="line"><span>              │     └─ CMD 加热</span></span>
<span class="line"><span>              └─ LENGTH=8</span></span>
<span class="line"><span></span></span>
<span class="line"><span>STM32：5A A5 00 05 A1 01 01 01 CHECK</span></span>
<span class="line"><span>                    │  │  └─ VALUE 0x01 成功</span></span>
<span class="line"><span>                    │  └─ ORIGIN 回显 0x01</span></span>
<span class="line"><span>                    └─ OP 写应答</span></span></code></pre></div><h3 id="_4-2-读加热" tabindex="-1">4.2 读加热 <a class="header-anchor" href="#_4-2-读加热" aria-label="Permalink to “4.2 读加热”">​</a></h3><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ESP32：5A A5 00 04 A1 02 01 CHECK          OP=读，ORIGIN=0x01，无 VALUE</span></span>
<span class="line"><span>STM32：5A A5 00 08 A1 03 01 … CHECK       OP=读应答，ORIGIN 回显，VALUE 4 字节</span></span></code></pre></div><h3 id="_4-3-实时数据通知" tabindex="-1">4.3 实时数据通知 <a class="header-anchor" href="#_4-3-实时数据通知" aria-label="Permalink to “4.3 实时数据通知”">​</a></h3><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>STM32：5A A5 00 12 C0 FF 00 （14 字节 VALUE）  CHECK</span></span>
<span class="line"><span>                    │  │  └─ ORIGIN=0x00</span></span>
<span class="line"><span>                    │  └─ OP 通知</span></span>
<span class="line"><span>                    └─ CMD 实时数据</span></span>
<span class="line"><span>LENGTH = 4 + 14 = 0x0012</span></span></code></pre></div><hr><h2 id="_5-与-ble-对照" tabindex="-1">5. 与 BLE 对照 <a class="header-anchor" href="#_5-与-ble-对照" aria-label="Permalink to “5. 与 BLE 对照”">​</a></h2><p>网关把 BLE <code>cmd</code> 换成下表 SPF <code>CMD</code>，把 BLE <code>cmd_type</code> 换成 SPF <code>OP</code>（对应关系见 <a href="/ahs-docs-page/common/spf-packet-v2.html">SPF 数据包格式 V2</a>）。透传时 ORIGIN=<code>0x01</code>。<strong>两边 cmd 数值不同</strong>，不能原样转发。</p><div class="vp-table-wrap"><table tabindex="0"><thead><tr><th>BLE cmd</th><th>SPF CMD</th><th>名称</th></tr></thead><tbody><tr><td><code>0x01</code></td><td><code>0xC0</code></td><td>实时数据</td></tr><tr><td><code>0x02</code></td><td><code>0x90</code></td><td>枕头基础高度</td></tr><tr><td><code>0x03</code></td><td><code>0xA7</code></td><td>负离子</td></tr><tr><td><code>0x04</code></td><td><code>0xA1</code></td><td>加热</td></tr><tr><td><code>0x05</code></td><td><code>0xA3</code></td><td>系统提示音</td></tr><tr><td><code>0x06</code></td><td><code>0x40</code></td><td>音乐通道</td></tr><tr><td><code>0x07</code></td><td><code>0x20</code></td><td>系统指示灯</td></tr><tr><td><code>0x08</code></td><td><code>0xCB</code></td><td>进入标定</td></tr><tr><td><code>0x09</code></td><td><code>0xCC</code></td><td>调节枕高</td></tr><tr><td><code>0x0A</code></td><td><code>0x21</code></td><td>智能睡眠模式</td></tr><tr><td><code>0x0B</code></td><td><code>0x22</code></td><td>PA 增益设置</td></tr><tr><td><code>0x10</code></td><td><code>0xCD</code></td><td>标定 1</td></tr><tr><td><code>0x11</code></td><td><code>0xCE</code></td><td>标定 2</td></tr><tr><td><code>0x14</code></td><td><code>0xCF</code></td><td>读气压（主板当前未处理，见 §6）</td></tr><tr><td><code>0x15</code></td><td><code>0xC6</code></td><td>智能匹配</td></tr><tr><td><code>0x17</code></td><td><code>0xA2</code></td><td>临时控制外设</td></tr><tr><td><code>0x18</code></td><td><code>0xD9</code></td><td>闹钟</td></tr><tr><td><code>0x19</code></td><td><code>0xDA</code></td><td>临时关闹钟</td></tr><tr><td><code>0x20</code></td><td><code>0xC2</code></td><td>日期时间</td></tr><tr><td><code>0x21</code></td><td><code>0x80</code></td><td>音乐音量</td></tr><tr><td><code>0x22</code></td><td><code>0x70</code></td><td>音乐播放器设置</td></tr><tr><td><code>0x23</code></td><td><code>0x81</code></td><td>音乐播放控制</td></tr><tr><td><code>0x24</code></td><td>—</td><td>设置产品类型（网关本地，无 SPF）</td></tr><tr><td><code>0x30</code></td><td><code>0xD0</code></td><td>请求睡眠报告</td></tr><tr><td><code>0x31</code></td><td><code>0xD1</code></td><td>报告传输状态</td></tr><tr><td><code>0x32</code></td><td><code>0xD2</code></td><td>睡眠报告</td></tr><tr><td><code>0x33</code></td><td><code>0xD3</code></td><td>报告原始数据</td></tr><tr><td><code>0x34</code></td><td><code>0xD5</code></td><td>假 BCG 数据</td></tr><tr><td><code>0xF0</code></td><td><code>0xC9</code></td><td>故障代码</td></tr><tr><td><code>0xF1</code></td><td><code>0xC8</code></td><td>固件版本</td></tr><tr><td><code>0xF2</code></td><td><code>0xDB</code></td><td>SIM120 蓝牙开关</td></tr><tr><td><code>0xF3</code></td><td><code>0xDE</code></td><td>工厂模式</td></tr><tr><td><code>0xF4</code></td><td><code>0xDF</code></td><td>恢复出厂（主板当前未处理，见 §6）</td></tr><tr><td><code>0xFA</code></td><td><code>0xE0</code></td><td>参数寄存器 1（<strong>【预留占位】</strong>）</td></tr><tr><td><code>0xFB</code></td><td><code>0xE1</code></td><td>参数寄存器 2</td></tr><tr><td><code>0xFC</code></td><td><code>0xE2</code></td><td>参数寄存器 3</td></tr></tbody></table></div><p>BLE 侧 WIFI <code>0x72</code>/<code>0x73</code>/<code>0x74</code>、读设备编号 <code>0x75</code>、设置产品类型 <code>0x24</code> 由 <strong>网关本地</strong>处理，不经过本串口。</p><p>VALUE 布局大体与 BLE 相同；差异已在 §2 标明（例如 <code>0x90</code> 读应答长度、<code>0xC2</code> 读应答两帧、<code>0xE1</code> 7 字节、标定双次写应答、关机应答极性）。</p><hr><h2 id="_6-保留命令" tabindex="-1">6. 保留命令 <a class="header-anchor" href="#_6-保留命令" aria-label="Permalink to “6. 保留命令”">​</a></h2><p><code>spf_cmd.h</code> 已枚举、当前 AHE04 主板 <strong>收包未处理</strong>（会打 <code>not support</code>）。网关不要当已实现功能去等应答。</p><div class="vp-table-wrap"><table tabindex="0"><thead><tr><th>cmd</th><th>名称</th></tr></thead><tbody><tr><td><code>0x10</code></td><td>ESP32 RGB 控制（STM32→ESP32，<strong>【预留】</strong>）</td></tr><tr><td><code>0x30</code></td><td>香薰</td></tr><tr><td><code>0x50</code></td><td>呼吸训练</td></tr><tr><td><code>0x60</code></td><td>气囊（旧）</td></tr><tr><td><code>0xA0</code></td><td>FINISH</td></tr><tr><td><code>0xB0</code></td><td>小眠睡眠数据</td></tr><tr><td><code>0xB2</code></td><td>小眠实时数据</td></tr><tr><td><code>0xCF</code></td><td>气压读取</td></tr><tr><td><code>0xD6</code></td><td>工作模式 0</td></tr><tr><td><code>0xD7</code></td><td>模式控制</td></tr><tr><td><code>0xDF</code></td><td>重置出厂设置</td></tr></tbody></table></div><p>实时气压可从 <code>0xC0</code> 的 <code>[12-13]</code> 或读 <code>0xE1</code> 取得。出厂复位若要做，需在主板补 <code>0xDF</code> 处理后再写入本文。</p>`,73)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};